const raw = $input.first().json;

// Information Extractor puts everything inside "output"
const d = raw.output ?? raw;

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined || value === "") return [];

  return String(value)
    .split(/[\n,;]+/)
    .map(x => x.trim())
    .filter(Boolean);
}

function toSingleItemArray(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined || value === "") return [];
  return [String(value).trim()];
}

return [
  {
    json: {
      candidate: {
        name: d.name ?? "",
        education: toSingleItemArray(d.education),
        skills: toArray(d.skills),
        experience: toSingleItemArray(d.experience),
        projects: toSingleItemArray(d.projects),
        languages: toArray(d.languages),
        work_authorization: toArray(d.work_authorization)
      },

      job_preferences: {
        target_roles: toArray(d.target_roles),
        locations: toArray(d.locations),
        employment_type: toArray(d.employment_type),
        minimum_salary: d.minimum_salary ?? null,
        max_experience_years:
          d.max_experience_years !== null &&
          d.max_experience_years !== undefined &&
          d.max_experience_years !== ""
            ? Number(d.max_experience_years)
            : null,
        preferred_industries: toArray(d.preferred_industries),
        avoid_keywords: toArray(d.avoid_keywords),
        minimum_fit_score:
          d.minimum_fit_score !== null &&
          d.minimum_fit_score !== undefined &&
          d.minimum_fit_score !== ""
            ? Number(d.minimum_fit_score)
            : 70
      }
    }
  }
];
